function languageSwitch(code) {
  return Object.keys(languages).map(key => {
    if (key === code) return `<span class="active" data-lang="${key}">${labels[key]}</span>`;
    const href = code === 'ru' ? `${key}/${slug}` : key === 'ru' ? `../${slug}` : `../${key}/${slug}`;
    return `<a data-lang="${key}" href="${href}">${labels[key]}</a>`;
  }).join('');
}

function calculator(t) {
  return `<section class="jackpot-calculator" data-jackpot-calculator aria-labelledby="jackpot-calc-title"><h3 id="jackpot-calc-title">${t.calcTitle}</h3><div class="calc-fields"><label>${t.odds}<input type="number" min="1" step="1" value="100000" inputmode="numeric" data-odds></label><label>${t.attempts}<input type="number" min="1" step="1" value="100" inputmode="numeric" data-attempts></label></div><div class="calc-results" aria-live="polite"><div><span>${t.result}</span><b data-probability>0.1000%</b></div><div><span>${t.expected}</span><b data-expected>0.001</b></div></div><p class="calc-error" data-error>${t.error}</p></section>`;
}

